from collections.abc import Sequence
from uuid import UUID

from sqlalchemy import delete, select
from sqlalchemy.orm import Session

from ai_knowledge_platform.models.document_chunk import (
    DocumentChunk as DocumentChunkModel,
)
from ai_knowledge_platform.services.chunking.types import (
    DocumentChunk as ChunkData,
)


class DocumentChunkRepository:
    """Persist chunks generated by document chunking."""

    def __init__(self, db: Session) -> None:
        self.db = db

    def replace_for_run(
        self,
        *,
        ingestion_run_id: UUID,
        chunks: Sequence[ChunkData],
    ) -> list[DocumentChunkModel]:
        """Replace all chunks belonging to an ingestion run."""
        self._validate_chunks(chunks)

        self.db.execute(
            delete(DocumentChunkModel).where(
                DocumentChunkModel.ingestion_run_id == ingestion_run_id,
            )
        )

        chunk_records = [
            DocumentChunkModel(
                ingestion_run_id=ingestion_run_id,
                chunk_index=chunk.chunk_index,
                content=chunk.content,
                token_count=chunk.token_count,
                start_char=chunk.start_char,
                end_char=chunk.end_char,
                page_start=chunk.page_start,
                page_end=chunk.page_end,
                chunk_metadata={},
            )
            for chunk in chunks
        ]

        self.db.add_all(chunk_records)
        self.db.flush()

        return chunk_records

    def list_by_run_id(
        self,
        ingestion_run_id: UUID,
    ) -> list[DocumentChunkModel]:
        """Return persisted chunks in their original order."""
        statement = (
            select(DocumentChunkModel)
            .where(
                DocumentChunkModel.ingestion_run_id == ingestion_run_id,
            )
            .order_by(DocumentChunkModel.chunk_index)
        )

        return list(self.db.scalars(statement).all())

    @staticmethod
    def _validate_chunks(chunks: Sequence[ChunkData]) -> None:
        """Validate chunk ordering before modifying persisted records."""
        for expected_index, chunk in enumerate(chunks):
            if chunk.chunk_index != expected_index:
                raise ValueError("Chunk indexes must be sequential and start at zero.")
